import React from 'react';
import Card from './Card';  // Assuming the Card component is in the same directory

const CardDisplay = () => {
  return (
    <div className="container mt-4">
      <div className="d-flex justify-content-start flex-wrap">
        <div className="card-container mx-2">
          <Card title="Pet 1" description="This is pet 1" image="https://via.placeholder.com/150" />
        </div>
        <div className="card-container mx-2">
          <Card title="Pet 2" description="This is pet 2" image="https://via.placeholder.com/150" />
        </div>
        <div className="card-container mx-2">
          <Card title="Pet 3" description="This is pet 3" image="https://via.placeholder.com/150" />
        </div>
        <div className="card-container mx-2">
          <Card title="Pet 4" description="This is pet 4" image="https://via.placeholder.com/150" />
        </div>
      </div>
    </div>
  );
}

export default CardDisplay;
